#!/usr/bin/env node
// generate-apps-network-i18n-sitemaps.cjs
// Split the apps-network sitemap into one file per language so each locale's
// URL set is directly discoverable (in addition to the combined file).
//
// Input : public/apps-network-sitemap.xml (generated by generate-apps-network-i18n.mjs)
// Output: public/sitemap-apps-network-<lang>.xml
//
// Usage : node scripts/generate-apps-network-i18n-sitemaps.cjs

const fs = require('fs');
const path = require('path');

const SITE = 'https://ziontechgroup.com';
const PUBLIC = path.join(process.cwd(), 'public');
const SOURCE = path.join(PUBLIC, 'apps-network-sitemap.xml');

// URL path prefix -> hreflang / filename code
const LANGS = [
  { code: 'en', prefix: '' },
  { code: 'pt-BR', prefix: 'pt/' },
  { code: 'es', prefix: 'es/' },
  { code: 'fr', prefix: 'fr/' },
  { code: 'de', prefix: 'de/' },
];

function langFor(urlPath) {
  const rel = urlPath.replace(SITE + '/', '');
  for (const l of LANGS) {
    if (l.prefix === '') {
      if (!/^(pt|es|fr|de)\//.test(rel)) return l;
    } else if (rel.startsWith(l.prefix)) {
      return l;
    }
  }
  return null;
}

function main() {
  if (!fs.existsSync(SOURCE)) {
    throw new Error(`missing ${SOURCE} — run scripts/generate-apps-network-i18n.mjs first`);
  }
  const xml = fs.readFileSync(SOURCE, 'utf8');
  const locs = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]);
  const groups = new Map(LANGS.map((l) => [l.code, []]));
  for (const loc of locs) {
    const l = langFor(loc);
    if (l) groups.get(l.code).push(loc);
  }
  for (const l of LANGS) {
    const rows = groups.get(l.code);
    const body = rows
      .map((u) => `  <url><loc>${u}</loc><changefreq>weekly</changefreq><priority>0.7</priority></url>`)
      .join('\n');
    const out = [
      '<?xml version="1.0" encoding="UTF-8"?>',
      `<!-- Apps Network sitemap — ${l.code}. Generated by scripts/generate-apps-network-i18n-sitemaps.cjs. -->`,
      '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
      body,
      '</urlset>',
      '',
    ].join('\n');
    const file = path.join(PUBLIC, `sitemap-apps-network-${l.code}.xml`);
    fs.writeFileSync(file, out);
    console.log(`${l.code}: ${rows.length} urls -> ${path.basename(file)}`);
  }
}

if (require.main === module) main();

module.exports = { langFor };
